int main(int argc,char**argv){long n=argc>1?atol(argv[1]):480000;double rate=argc>2?atof(argv[2]):44100;int mode=argc>3?atoi(argv[3]):0;int ch=argc>4?atoi(argv[4]):1;FILE*dump=argc>5?fopen(argv[5],"wb"):NULL;if(n<1||n>2000000||ch<1||ch>8||rate<8000||rate>96000||mode<0||mode>1)return 64;int err;SRC_STATE*s=src_new(SRC_SINC_FASTEST,ch,&err);float*in=calloc((n+10)*ch,sizeof(float));long capacity=(n+10)*2;if(capacity<4096)capacity=4096;float*out=calloc(capacity*ch,sizeof(float));if(!s||!in||!out)return 70;for(long i=0;i<n;i++)for(int c=0;c<ch;c++)in[i*ch+c]=0.1f*sinf((float)i*(0.071f+c*0.013f));long used=0,made=0;double ratio=rate/48000.;while(used<n){long k=mode==1?n:((n-used)>1024?1024:n-used);SRC_DATA d={.data_in=in+used*ch,.data_out=out,.input_frames=k,.output_frames=(long)ceil(k*ratio),.end_of_input=mode==1,.src_ratio=ratio};src_set_ratio(s,ratio);err=src_process(s,&d);if(err)return 2;used+=d.input_frames_used;made+=d.output_frames_gen;if(dump)fwrite(out,sizeof(float),d.output_frames_gen*ch,dump);if(!d.input_frames_used)return 3;}long drain=0;for(;;){SRC_DATA d={.data_in=in,.data_out=out,.input_frames=0,.output_frames=4096,.end_of_input=1,.src_ratio=ratio};err=src_process(s,&d);if(err)return 4;if(!d.output_frames_gen)break;made+=d.output_frames_gen;if(dump)fwrite(out,sizeof(float),d.output_frames_gen*ch,dump);drain+=d.output_frames_gen;}printf("n=%ld rate=%.0f mode=%d made=%ld drain=%ld expected_floor=%ld\n",n,rate,mode,made,drain,(long)floor(n*ratio));if(dump)fclose(dump);src_delete(s);free(in);free(out);}
